const SG_F='font-family="Nunito Sans, sans-serif"';
const SG_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${SG_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const SG_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const SG_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.ex||''}/>`;
/* a curve of computed points: f(t) for t in [t0,t1], mapped to x in [x0,x1] and y = yc - k*f */
const SG_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=120)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`};
const SG_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return SG_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const SG_X=(x,y,s,col,w=5)=>SG_L(x-s,y-s,x+s,y+s,col,w)+SG_L(x-s,y+s,x+s,y-s,col,w);
/* an s-plane: sigma axis from x0 to x1 at height y, jw axis at x = xj from yt to yb */
const SG_plane=(x0,x1,y,xj,yt,yb)=>SG_L(x0,y,x1,y,'#ADB5BD',2)+SG_L(xj,yb,xj,yt,'#ADB5BD',2)+SG_T(x1,y+26,'σ',{fs:22,a:'end',fill:'#5C6577'})+SG_T(xj+8,yt+18,'jω',{fs:22,fill:'#5C6577'});
const SG_GR='#5C6577';
/* the lesson's signals, computed */
const SG_wrong=t=>t<0?0:Math.exp(-t)+2*Math.exp(-3*t);               // (e^-t + 2e^-3t)u(t)
const SG_two=t=>t<0?-Math.exp(-t):2*Math.exp(-3*t);                   // -e^-t u(-t) + 2e^-3t u(t)
const SG_step=t=>0.5-Math.exp(-t)+0.5*Math.exp(-2*t);                 // step response from rest
const SG_comp=t=>0.5+Math.exp(-t)-0.5*Math.exp(-2*t);                 // complete response, y(0-) = 1
